import{_ as t,o as a,c as r,ag as i}from"./chunks/framework.CbQjVMS6.js";const p=JSON.parse('{"title":"Product lifecycle management for small manufacturers","description":"","frontmatter":{},"headers":[],"relativePath":"insights/plm-for-smes.md","filePath":"insights/plm-for-smes.md","lastUpdated":1793948662000}'),n={name:"insights/plm-for-smes.md"};function o(s,e,l,d,h,c){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="product-lifecycle-management-for-small-manufacturers" tabindex="-1">Product lifecycle management for small manufacturers <a class="header-anchor" href="#product-lifecycle-management-for-small-manufacturers" aria-label="Permalink to &quot;Product lifecycle management for small manufacturers&quot;">​</a></h1><p><em>Published 6 November 2026 · 7 min read</em></p><p>Product lifecycle management (PLM) is the discipline of keeping product information coherent from the first requirement to retirement: requirements, design files, bills of materials, changes, quality records and supplier data. Large manufacturers treat it as essential infrastructure. Small and mid-sized manufacturers often treat it as unaffordable.</p><p>Both positions are understandable. Traditional PLM suites are priced and implemented for organisations with dedicated IT teams, long rollouts and complex approval hierarchies. A thirty-person manufacturer needs the outcome, not the apparatus.</p><p>This article describes what a small manufacturer should demand from PLM, the minimum viable scope, and the order in which to adopt it. It also explains why PiePLM is published as a design blueprint rather than a finished product.</p><h2 id="why-product-information-breaks-down" tabindex="-1">Why product information breaks down <a class="header-anchor" href="#why-product-information-breaks-down" aria-label="Permalink to &quot;Why product information breaks down&quot;">​</a></h2><p>A manufacturer without a product data system usually relies on a combination of shared drives, spreadsheets, email and the ERP. This works until it does not. Typical failure points:</p><ul><li><strong>The drawing and the BOM disagree.</strong> Engineering releases revision C; manufacturing builds revision B because the BOM was updated by email.</li><li><strong>Nobody knows why a change was made.</strong> A part was substituted two years ago. The reason lived in a departed engineer&#39;s inbox.</li><li><strong>Supplier data is duplicated.</strong> Three spreadsheets list the same supplier with different lead times and contact details.</li><li><strong>Quality issues repeat.</strong> A non-conformance is closed with a corrective action that is never linked to the affected product revision.</li><li><strong>Audits take weeks.</strong> Reconstructing the design history for a customer or regulator becomes a manual investigation.</li></ul><p>These are information problems, not CAD problems. A better CAD tool will not fix them.</p><h2 id="what-small-manufacturers-actually-need" tabindex="-1">What small manufacturers actually need <a class="header-anchor" href="#what-small-manufacturers-actually-need" aria-label="Permalink to &quot;What small manufacturers actually need&quot;">​</a></h2><p>A useful PLM for an SME has a narrow scope and a low operational burden:</p><h3 id="_1-a-single-product-record" tabindex="-1">1. A single product record <a class="header-anchor" href="#_1-a-single-product-record" aria-label="Permalink to &quot;1. A single product record&quot;">​</a></h3><p>Every product has one identity, one current revision and one owner. Drawings, documents and BOMs attach to that identity. Links are explicit, not implied by folder names.</p><h3 id="_2-requirements-and-traceability" tabindex="-1">2. Requirements and traceability <a class="header-anchor" href="#_2-requirements-and-traceability" aria-label="Permalink to &quot;2. Requirements and traceability&quot;">​</a></h3><p>Requirements are captured, categorised and linked to design items and tests. The goal is not a formal requirements management process; it is the ability to answer “why does this product have this feature?” and “what proves that it works?”.</p><h3 id="_3-bill-of-materials-with-structure" tabindex="-1">3. Bill of materials with structure <a class="header-anchor" href="#_3-bill-of-materials-with-structure" aria-label="Permalink to &quot;3. Bill of materials with structure&quot;">​</a></h3><p>A BOM should be a structured tree with quantities, units, reference designators and effectivity. It should be versioned with the product, not maintained as a spreadsheet attachment.</p><h3 id="_4-change-management" tabindex="-1">4. Change management <a class="header-anchor" href="#_4-change-management" aria-label="Permalink to &quot;4. Change management&quot;">​</a></h3><p>A change request states what changes, why, who is affected and what approval is required. When approved, it creates a new revision and records the decision. The workflow can be simple; the important property is that changes are recorded, not remembered.</p><h3 id="_5-quality-and-supplier-links" tabindex="-1">5. Quality and supplier links <a class="header-anchor" href="#_5-quality-and-supplier-links" aria-label="Permalink to &quot;5. Quality and supplier links&quot;">​</a></h3><p>Non-conformances, corrective actions and supplier evaluations should reference the product and revision they concern. This turns quality data into product history instead of isolated tickets.</p><h3 id="_6-an-api-for-everything" tabindex="-1">6. An API for everything <a class="header-anchor" href="#_6-an-api-for-everything" aria-label="Permalink to &quot;6. An API for everything&quot;">​</a></h3><p>Small teams cannot afford a year of integration work. Products, BOMs, changes and documents should be reachable through a documented API so the ERP, MES or an internal tool can read them.</p><p>Notice what is absent: portfolio management, programme governance, simulation data management and multi-site configuration. Those can come later if the company grows into them.</p><h2 id="adoption-order" tabindex="-1">Adoption order <a class="header-anchor" href="#adoption-order" aria-label="Permalink to &quot;Adoption order&quot;">​</a></h2><p>Trying to implement every module at once is the most common way SME PLM projects fail. A safer sequence:</p><ol><li><strong>Product identity and documents.</strong> Get every product, drawing and specification into one record with an owner. This alone removes a surprising amount of confusion.</li><li><strong>BOM structure.</strong> Replace the master spreadsheet with a versioned tree. Keep the spreadsheet export for people who need it.</li><li><strong>Change workflow.</strong> Introduce a lightweight change request and approval. Start with engineering changes only.</li><li><strong>Requirements traceability.</strong> Link requirements to design and test evidence for new products; retrofit old products selectively.</li><li><strong>Quality and supplier integration.</strong> Connect non-conformances and supplier records to product revisions.</li><li><strong>Reporting and AI assistance.</strong> Only after the data is coherent is it worth building dashboards or agent workflows on top.</li></ol><p>Each step should deliver value on its own. If step two requires step five to be useful, the scope is wrong.</p><h2 id="where-ai-helps-and-where-it-does-not" tabindex="-1">Where AI helps, and where it does not <a class="header-anchor" href="#where-ai-helps-and-where-it-does-not" aria-label="Permalink to &quot;Where AI helps, and where it does not&quot;">​</a></h2><p>AI is useful for:</p><ul><li>drafting requirement summaries and change descriptions</li><li>extracting structured data from documents and drawings metadata</li><li>answering questions over product history through a searchable knowledge layer</li><li>flagging inconsistencies between a BOM and a drawing</li></ul><p>AI is not a substitute for:</p><ul><li>a defined product identity</li><li>an approval workflow with named owners</li><li>version control for design artifacts</li><li>a data model that distinguishes a product from a revision from a part</li></ul><p>Adding an assistant to inconsistent data produces faster inconsistency. The data model comes first.</p><h2 id="the-pieplm-position" tabindex="-1">The PiePLM position <a class="header-anchor" href="#the-pieplm-position" aria-label="Permalink to &quot;The PiePLM position&quot;">​</a></h2><p><a href="https://pieteams.github.io/pieplm/" target="_blank" rel="noreferrer">PiePLM</a> is an open-source project exploring this narrower model. It is currently in the documentation and design phase: the public repository contains the problem statement, market research, architecture notes and module design, not an executable release.</p><p>We publish it as a blueprint for three reasons:</p><ul><li><strong>Evaluation before commitment.</strong> Manufacturers can review the proposed model and workflows before investing in implementation.</li><li><strong>Community input.</strong> Consultants and engineers can challenge the design while it is still cheap to change.</li><li><strong>Honest expectations.</strong> A design document should not pretend to be a shipped product.</li></ul><p>The intended architecture is a Go service with PostgreSQL, a structured product and BOM model, configurable approval flows, and an MCP interface so that AI agents can query product knowledge through the same contract as human users. The project will publish implementation milestones in the repository as they are completed.</p><h2 id="a-buyer-s-checklist" tabindex="-1">A buyer&#39;s checklist <a class="header-anchor" href="#a-buyer-s-checklist" aria-label="Permalink to &quot;A buyer&#39;s checklist&quot;">​</a></h2><p>If you are evaluating any PLM system as an SME, ask:</p><ul><li>Can I own and export my data without a vendor tool?</li><li>Is the product model revision-aware, or does it treat revisions as file names?</li><li>Can I start with product records and add modules later?</li><li>Is there a documented API, or only a user interface?</li><li>What is the total cost of ownership over five years, including implementation?</li><li>Can I run it on my own infrastructure?</li><li>What happens to my data if I stop paying?</li></ul><p>The answers matter more than the feature matrix. A small manufacturer does not need every PLM capability. It needs one coherent product record, a change history and the freedom to leave.</p><h2 id="further-reading" tabindex="-1">Further reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to &quot;Further reading&quot;">​</a></h2><ul><li><a href="https://pieteams.github.io/pieplm/getting-started/what-is-pieplm" target="_blank" rel="noreferrer">What is PiePLM</a> — the problem and the proposed approach</li><li><a href="https://pieteams.github.io/pieplm/getting-started/plm-systems" target="_blank" rel="noreferrer">PLM systems</a> — a survey of the commercial landscape</li><li><a href="https://pieteams.github.io/pieplm/guide/architecture" target="_blank" rel="noreferrer">PiePLM architecture</a> — the intended system design</li></ul>',45)])])}const m=t(n,[["render",o]]);export{p as __pageData,m as default};
